1	// Acceptance tests for the change request:
2	//   "Let me sort a project's invoices by their due date."
3	//
4	// A project's detail page gains a control (invoice-sort-due) that reorders the invoice rows by their
5	// DUE date, earliest-due first. Activating it does not add or drop any invoice — it only changes the
6	// order the existing rows appear in.
7	//
8	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed; the sort is driven
9	// through the control. Seed honours invoices: { id, projectId, amount, issuedDate, dueDate, status }.
10	//
11	// Order is asserted format-tolerantly and position-tolerantly: we read the invoice-row-<id> elements
12	// in DOM order and compare the sequence of row ids. The seed is constructed so the due-date ascending
13	// order is a DISTINCTIVE permutation — one that id order, reverse-id order, amount order and
14	// issued-date order all FAIL to produce — so passing requires sorting by due date specifically, and
15	// not leaving the rows as seeded, reversing them, or sorting by some other column.
16	import { test, expect, type Page } from '@playwright/test';
17	import { resetAndSeed } from '../support/seed';
18	
19	// The row ids, in the order the invoice rows currently appear on the page.
20	async function invoiceRowOrder(page: Page): Promise<string[]> {
21	  return page
22	    .locator('[data-testid^="invoice-row-"]')
23	    .evaluateAll((els) => els.map((el) => el.getAttribute('data-testid') ?? ''));
24	}
25	
26	test.describe('sort invoices by due date', () => {
27	  test('activating the control orders the invoices earliest-due first', async ({ page }) => {
28	    await resetAndSeed({
29	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
30	      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
31	      // Due-date ascending order is 2 (Jan) -> 1 (Mar) -> 3 (Dec) == [2, 1, 3], which is NOT the id
32	      // order [1,2,3], NOT reverse [3,2,1], NOT amount order (100,200,300 -> [2,3,1]) and NOT issued
33	      // order (Feb,Jul,Nov -> [3,2,1]). Only a genuine due-date sort yields [2,1,3].
34	      invoices: [
35	        { id: 1, projectId: 1, amount: 300, issuedDate: '2025-11-01', dueDate: '2025-03-10' },
36	        { id: 2, projectId: 1, amount: 100, issuedDate: '2025-07-01', dueDate: '2025-01-05' },
37	        { id: 3, projectId: 1, amount: 200, issuedDate: '2025-02-01', dueDate: '2025-12-20' },
38	      ],
39	    });
40	
41	    await page.goto('/projects');
42	    await page.getByTestId('project-open-1').click();
